from pypeline import MAIN, hw_func, uint8_t

@hw_func
def add1(x: uint8_t) -> uint8_t:
    return x + 1

@hw_func
def mix(x: uint8_t, y: uint8_t) -> uint8_t:
    a: uint8_t = add1(x)
    b: uint8_t = add1(y)
    return a ^ b

@MAIN
def pipelinec_scale_equiv(x: uint8_t, y: uint8_t) -> uint8_t:
    return mix(x, y) + add1(x)
PY
